    # ─────────────────────────────────────────────────────────────────────────
    # VECTORIZED DIFFERENCING & POLYNOMIAL EXPANSION
    # ─────────────────────────────────────────────────────────────────────────

    def _diff_series(self, series: np.ndarray, lag: int = 1, order: int = 1) -> np.ndarray:
        # Apply lag-L difference operator (1 - B^L)^order to a 1D series: y_t - y_{t-L}
        res = series.copy()
        for _ in range(order):
            res = res[lag:] - res[:-lag]
        return res

    def _diff_matrix(self, mat: np.ndarray, lag: int = 1, order: int = 1) -> np.ndarray:
        # Apply lag-L difference operator (1 - B^L)^order column-wise to a 2D exogenous matrix X
        res = mat.copy()
        for _ in range(order):
            res = res[lag:, :] - res[:-lag, :]
        return res

    def _difference_array(self, arr: np.ndarray, is_2d: bool = False) -> Tuple[np.ndarray, np.ndarray]:
        diff_fn = self._diff_matrix if is_2d else self._diff_series
        # Stage 1: Regular differencing y^(d)_t = (1 - B)^d y_t to remove non-seasonal stochastic trend
        reg_diff = arr.copy()
        if self.d > 0:
            reg_diff = diff_fn(reg_diff, lag=1, order=self.d)

        # Stage 2: Seasonal differencing w_t = (1 - B^s)^D y^(d)_t to remove seasonal unit roots at lag s
        full_diff = reg_diff.copy()
        if self.D > 0 and self.s > 1:
            full_diff = diff_fn(full_diff, lag=self.s, order=self.D)

        # Return both intermediate reg_diff and fully differenced full_diff for two-stage inverse integration
        return reg_diff, full_diff

    def _integrate_differencing(self, w_forecast: np.ndarray, H: int) -> np.ndarray:
        """Invert seasonal and regular differencing to recover target scale."""
        # Step 1: Invert seasonal differencing (1 - B^s)^D
        # Since w_t = y^(d)_t - y^(d)_{t-s}, reconstruct y^(d)_{T+h} = w_{T+h} + y^(d)_{T+h-s}
        reg_pred = list(self._w_reg)
        w_list = list(w_forecast)
        for h in range(H):
            val = w_list[h]
            if self.D > 0 and self.s > 1:
                val += reg_pred[-self.s]
            reg_pred.append(val)
        y_reg_pred = reg_pred[-H:]

        # Step 2: Invert regular differencing (1 - B)^d
        # Since y^(d)_t = y_t - y_{t-1}, reconstruct y_{T+h} = y^(d)_{T+h} + y_{T+h-1}
        y_recon = list(self._raw_y)
        for h in range(H):
            val = y_reg_pred[h]
            if self.d > 0:
                val += y_recon[-1]
            y_recon.append(val)
        return np.array(y_recon[-H:], dtype=np.float64)

    def _expand_polynomials(self, params: np.ndarray) -> Tuple[np.ndarray, np.ndarray, float, Optional[np.ndarray]]:
        """Expand AR and MA parameter vectors into discrete lag polynomials via convolution."""
        idx = 0
        # Non-seasonal AR polynomial: phi(B) = 1 - phi_1*B - ... - phi_p*B^p
        # Negative signs reflect moving AR terms to the LHS of phi*(B) u_t = theta*(B) eps_t
        ar_nonseas = np.array([1.0] + [-params[idx + i] for i in range(self.p)], dtype=np.float64)
        idx += self.p

        # Non-seasonal MA polynomial: theta(B) = 1 + theta_1*B + ... + theta_q*B^q
        ma_nonseas = np.array([1.0] + [params[idx + j] for j in range(self.q)], dtype=np.float64)
        idx += self.q

        # Seasonal AR polynomial: Phi(B^s) = 1 - Phi_1*B^s - ... - Phi_P*B^(P*s)
        # Convolving coefficient arrays multiplies the polynomials: phi*(B) = phi(B) * Phi(B^s)
        if self.P > 0 and self.s > 1:
            poly_P = np.zeros(self.P * self.s + 1, dtype=np.float64)
            poly_P[0] = 1.0
            for i in range(self.P):
                poly_P[(i + 1) * self.s] = -params[idx + i]
            ar_poly = np.convolve(ar_nonseas, poly_P)
            idx += self.P
        else:
            ar_poly = ar_nonseas

        # Seasonal MA polynomial: Theta(B^s) = 1 + Theta_1*B^s + ... + Theta_Q*B^(Q*s)
        # Convolving coefficient arrays multiplies the polynomials: theta*(B) = theta(B) * Theta(B^s)
        if self.Q > 0 and self.s > 1:
            poly_Q = np.zeros(self.Q * self.s + 1, dtype=np.float64)
            poly_Q[0] = 1.0
            for j in range(self.Q):
                poly_Q[(j + 1) * self.s] = params[idx + j]
            ma_poly = np.convolve(ma_nonseas, poly_Q)
            idx += self.Q
        else:
            ma_poly = ma_nonseas

        # Extract optional drift/intercept c and exogenous regression coefficients beta
        intercept = float(params[idx]) if self.include_constant else 0.0
        if self.include_constant:
            idx += 1

        n_exog = len(self._exog_names)
        beta = np.array(params[idx:idx + n_exog], dtype=np.float64) if n_exog > 0 else None
        return ar_poly, ma_poly, intercept, beta

